import { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import axios from "axios";

export default function Perfil() {
  const { id } = useParams();
  const [usuario, setUsuario] = useState(null);

  useEffect(() => {
    const buscarUsuario = async () => {
      try {
        const resposta = await axios.get(`http://localhost:3001/usuarios/${id}`);
        setUsuario(resposta.data);
      } catch (erro) {
        console.error("Erro ao buscar usuário:", erro);
      }
    };

    buscarUsuario();
  }, [id]);

  if (!usuario) return <p>Carregando...</p>;

  return (
    <div style={{ padding: "20px" }}>
      <h2>Perfil de {usuario.nome}</h2>
      <img
        src={`http://localhost:3001${usuario.foto}`}
        alt="Foto de perfil"
        style={{ width: 200, borderRadius: 10, marginBottom: 20 }}
      />
      <p><strong>Nome:</strong> {usuario.nome}</p>
      <p><strong>Idade:</strong> {usuario.idade}</p>
      <p><strong>Rua:</strong> {usuario.rua}</p>
      <p><strong>Bairro:</strong> {usuario.bairro}</p>
      <p><strong>Estado:</strong> {usuario.estado}</p>
      <p><strong>Biografia:</strong> {usuario.biografia}</p>
    </div>
  );
}
